/* A community's short description and its member links (round 26), run after part 81. Two new columns on `communities`. `summary`, the short description a visitor reads on the community's card: plain text, at most 160 characters, null when the creator has not written one (the card then falls back to the tagline, then to the start of the description; nothing is filled in for existing communities). `member_links`, up to four shortcuts members see inside the community (each an object with an id, a name, an address, an optional icon and whether it is hidden), an empty list by default. Both are server only: neither is one of the columns members and visitors can read with the browser's keys, and only the service role reads and writes them, after the owner and admin checks in the app; the member links reach a member only through the server, for an active member. No existing row changes beyond the empty defaults. Until it runs, the Page editor says the short description and member links need this update, and everything else on the page saves as before. Where part 81 is missing it skips itself with a notice. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.communities') IS NULL THEN RAISE NOTICE 'summary and member links: there is no communities table, run part 81 first.'; RETURN; END IF; ALTER TABLE public.communities ADD COLUMN IF NOT EXISTS summary text; ALTER TABLE public.communities ADD COLUMN IF NOT EXISTS member_links jsonb NOT NULL DEFAULT '[]'::jsonb; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'communities_summary_length' AND conrelid = 'public.communities'::regclass) THEN ALTER TABLE public.communities ADD CONSTRAINT communities_summary_length CHECK (summary IS NULL OR char_length(summary) <= 160); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'communities_member_links_shape' AND conrelid = 'public.communities'::regclass) THEN ALTER TABLE public.communities ADD CONSTRAINT communities_member_links_shape CHECK (CASE WHEN jsonb_typeof(member_links) = 'array' THEN jsonb_array_length(member_links) <= 4 AND pg_column_size(member_links) <= 16384 ELSE false END); END IF; REVOKE SELECT (summary, member_links), INSERT (summary, member_links), UPDATE (summary, member_links) ON public.communities FROM PUBLIC, anon, authenticated; GRANT SELECT (summary, member_links), UPDATE (summary, member_links) ON public.communities TO service_role; END $do$;
notify pgrst, 'reload schema';
